mat2 rot(float a) {
return mat2(cos(a),sin(a),-sin(a),cos(a));
}
vec4 formula(vec4 p) {
p.xz = abs(p.xz+1.)-abs(p.xz-1.)-p.xz;
p.y-=.25;
p.xy = multiply(p.xy, rot(radians(35.)));
