float de(vec3 pos) {
#ifdef WAVES
pos.y+=sin(pos.z-t*6.)*.15;
// waves!
#endif
float hid=0.;
vec3 tpos=pos;
tpos.z=abs(3.-mod_conv(tpos.z,6.));
vec4 p=vec4(tpos,1.);
for (int i=0; i<4; i++) {p=formula(p);}
float fr=(length(max(vec2(0., 0.),p.yz-1.5))-1.)/p.w;
float ro=max(abs(pos.x+1.)-.3,pos.y-.35);
ro=max(ro,-max(abs(pos.x+1.)-.1,pos.y-.5));
pos.z=abs(.25-mod_conv(pos.z,.5));
ro=max(ro,-max(abs(pos.z)-.2,pos.y-.3));
ro=max(ro,-max(abs(pos.z)-.01,-pos.y+.32));
float d=min(fr,ro);
return d;
}
vec3 path(float ti) {
ti*=1.5;
vec3  p=vec3(sin(ti),(1.-sin(ti*2.))*.5,-ti*5.)*.5;
return p;
}
float edge=0.;
vec3 normal(vec3 p) {
vec3 e = vec3(0.0,det*5.,0.0);
float d1=de(p-e.yxx),d2=de(p+e.yxx);
float d3=de(p-e.xyx),d4=de(p+e.xyx);
float d5=de(p-e.xxy),d6=de(p+e.xxy);
float d=de(p);
edge=abs(d-0.5*(d2+d1))+abs(d-0.5*(d4+d3))+abs(d-0.5*(d6+d5));
// edge finder
edge=min(1.,pow(edge,.55)*15.);
return normalize(vec3(d1-d2,d3-d4,d5-d6));
}
vec4 rainbow(vec2 p)
{
float q = max(p.x,-0.1);
float s = sin(p.x*7.0+t*70.0)*0.08;
p.y+=s;
p.y*=1.1;
vec4 c;
if (p.x>0.0) c=vec4( 0.0 , 0.0 , 0.0 , 0.0 ); else
if (0.0/6.0<p.y&&p.y<1.0/6.0) c= vec4( 255.0 , 43.0 , 14.0 , 255.0 )/255.0; else
if (1.0/6.0<p.y&&p.y<2.0/6.0) c= vec4( 255.0 , 168.0 , 6.0 , 255.0 )/255.0; else
if (2.0/6.0<p.y&&p.y<3.0/6.0) c= vec4( 255.0 , 244.0 , 0.0 , 255.0 )/255.0; else
if (3.0/6.0<p.y&&p.y<4.0/6.0) c= vec4( 51.0 , 234.0 , 5.0 , 255.0 )/255.0; else
if (4.0/6.0<p.y&&p.y<5.0/6.0) c= vec4( 8.0 , 163.0 , 255.0 , 255.0 )/255.0; else
if (5.0/6.0<p.y&&p.y<6.0/6.0) c= vec4( 122.0 , 85.0 , 255.0 , 255.0 )/255.0; else
if (abs(p.y)-.05<0.0001) c=vec4(0.,0.,0.,1.); else
if (abs(p.y-1.)-.05<0.0001) c=vec4(0.,0.,0.,1.); else
c=vec4( 0.0 , 0.0 , 0.0 , 0.0 );
c.a*=.8-min(.8,abs(p.x*.08));
c.xyz=mix(c.xyz,vec3(length(c.xyz), length(c.xyz), length(c.xyz)),.15);
return c;
}
vec4 nyan(vec2 p)
{
vec2 uv_conv = p*vec2(0.4,1.0);
float ns=3.0;
float nt = uTime*ns; nt-=mod_conv(nt,240.0/256.0/6.0); nt = mod_conv(nt,240.0/256.0);
float ny = mod_conv(uTime*ns,1.0); ny-=mod_conv(ny,0.75); ny*=-0.05;
vec4 color = texture(iChannel1,vec2(uv_conv.x/3.0+210.0/256.0-nt+0.05,.5-uv_conv.y-ny));
if (uv_conv.x<-0.3) color.a = 0.0;
if (uv_conv.x>0.2) color.a=0.0;
// crop the bottom cats
if (uv_conv.y<-0.3) color.a = 0.0;
return color;
}
vec3 raymarch(in vec3 from, in vec3 dir)
{
edge=0.;
vec3 p, norm;
float d=100.;
float totdist=0.;
for (int i=0; i<RAY_STEPS; i++) {
if (d>det*totdist && totdist<25.0) {
p=from+totdist*dir;
d=de(p);
det=detail*exp(.13*totdist);
totdist+=d;
}
}
vec3 col=vec3(0., 0., 0.);
p-=(det-d)*dir;
norm=normal(p);
#ifdef SHOWONLYEDGES
col=1.-vec3(edge);
// show wireframe version
#else
col=(1.-abs(norm))*max(0.,1.-edge*.8);
// set normal as color with dark edges
#endif
totdist=clamp(totdist,0.,26.);
dir.y-=.02;
// float sunsize=7.-max(0.,texture(iChannel0,vec2(.6,.2)).x)*5.;
// 4.6: very bright, 7.6: small
float sunsize = 7.6;
#ifdef bass_smooth
sunsize -= 2.0 * vis_shift;
if (vis_version ==  1) {
sunsize -= clamp( 0.0 , 2.0 ,bass_smooth)*1.5*vis_intensity;
}
else if (vis_version ==  2) {
sunsize -= smoothstep( 0.0 , 2.0 ,audioLowSmooth)*1.4*vis_intensity;
}
else {
sunsize -= vis_intensity;
}
#else
sunsize -= smoothstep( 0.0 , 2.0 ,audioLowSmooth)*1.4;
#endif
// responsive sun size
float an=atan(dir.x,dir.y)+uTime*1.5;
// angle for drawing and rotating sun
float s=pow(clamp(1.0-length(dir.xy)*sunsize-abs(.2-mod_conv(an,.4)),0.,1.),.1);
// sun
float sb=pow(clamp(1.0-length(dir.xy)*(sunsize-.2)-abs(.2-mod_conv(an,.4)),0.,1.),.1);
// sun border
float sg=pow(clamp(1.0-length(dir.xy)*(sunsize-4.5)-.5*abs(.2-mod_conv(an,.4)),0.,1.),3.);
// sun rays
float y=mix(.45,1.2,pow(smoothstep(0.,1.,.75-dir.y),2.))*(1.-sb*.5);
// gradient sky
vec3 backg=vec3(0.5,0.,1.)*((1.-s)*(1.-sg)*y+(1.-sb)*sg*vec3(1.,.8,0.15)*3.);
backg+=vec3(1.,.9,.1)*s;
backg=max(backg,sg*vec3(1.,.9,.5));
col=mix(vec3(1.,.9,.3),col,exp(-.004*totdist*totdist));
// distant fading to sun color
if (totdist>25.) col=backg;
// hit background
col=pow(col,vec3(GAMMA,GAMMA,GAMMA))*BRIGHTNESS;
col=mix(vec3(length(col), length(col), length(col)),col,SATURATION);
#ifdef SHOWONLYEDGES
col=1.-vec3(length(col), length(col), length(col));
#else
col*=vec3(1.,.9,.85);
#ifdef NYAN
dir.yx =multiply(dir.yx,rot(dir.x));
vec2 ncatpos=(dir.xy+vec2(-3.+mod_conv(-t,6.),-.27));
vec4 ncat=nyan(ncatpos*5.);
vec4 rain=rainbow(ncatpos*10.+vec2(.8,.5));
if (totdist>8.) col=mix(col,max(vec3(.2,.2,.2),rain.xyz),rain.a*.9);
if (totdist>8.) col=mix(col,max(vec3(.2,.2,.2),ncat.xyz),ncat.a*.9);
#endif
#endif
return col;
}
vec3 move(inout vec3 dir) {
vec3 go=path(t);
vec3 adv=path(t+.7);
float hd=de(adv);
vec3 advec=normalize(adv-go);
float an=adv.x-go.x; an*=min(1.,abs(adv.z-go.z))*sign(adv.z-go.z)*.7;
dir.xy = multiply(dir.xy, transpose(mat2(cos(an),sin(an),-sin(an),cos(an))));
an=advec.y*1.7;
dir.yz = multiply(dir.yz, transpose(mat2(cos(an),sin(an),-sin(an),cos(an))));
an=atan(advec.x,advec.z);
dir.xz = multiply(dir.xz, transpose(mat2(cos(an),sin(an),-sin(an),cos(an))));
return go;
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec4 fragColor = 0;
// CONV: Center on screen, then try some uAspect correction
uv = (uv * 2.0) - 1.0;
uv *= uAspect.xy;
// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
uv = vec2(uv.x, -uv.y);
vec2 fragCoord  = uv;
// uv = fragCoord.xy / uv.xy*2.-1.;
vec2 oriuv=uv;
// uv.y*=uv.y/uv.x;
// vec2 M=(mouse.xy/uv.xy-.5)*3.;
vec2 M = vec2(-mouse.x+0.5, mouse.y-0.5)*1.5;
if (mouse.z<1.) M=vec2(0.,-0.05);
// "zoom"
float fov=.9-max(0.,.7-uTime*.3);
vec3 dir=normalize(vec3(uv*fov,1.));
dir.yz=multiply(dir.yz,rot(M.y));
dir.xz=multiply(dir.xz,rot(M.x));
vec3 origin=vec3(-1.,.7,0.);
vec3 from=origin+move(dir);
from.x += 2;
from.y += 0.05;
// from.x += -1.1;
// from.y += -0.9;
vec3 color=raymarch(from,dir);
#ifdef BORDER
color=mix(vec3(0., 0., 0.),color,pow(max(0.,.95-length(oriuv*oriuv*oriuv*vec2(1.05,1.1))),.3));
#endif
fragColor = vec4(color,1.);
ret = fragColor;
  fragColor = vec4(ret, 1.0);
}

