c=vec4( 0.0 , 0.0 , 0.0 , 0.0 );
c.a*=.8-min(.8,abs(p.x*.08));
c.xyz=mix(c.xyz,vec3(length(c.xyz), length(c.xyz), length(c.xyz)),.15);
return c;
}
vec4 nyan(vec2 p)
{
vec2 uv_conv = p*vec2(0.4,1.0);
float ns=3.0;
float nt = uTime*ns; nt-=mod_conv(nt,240.0/256.0/6.0); nt = mod_conv(nt,240.0/256.0);
float ny = mod_conv(uTime*ns,1.0); ny-=mod_conv(ny,0.75); ny*=-0.05;
vec4 color = texture(iChannel1,vec2(uv_conv.x/3.0+210.0/256.0-nt+0.05,.5-uv_conv.y-ny));
if (uv_conv.x<-0.3) color.a = 0.0;
if (uv_conv.x>0.2) color.a=0.0;
// crop the bottom cats
if (uv_conv.y<-0.3) color.a = 0.0;
return color;
}
vec3 raymarch(in vec3 from, in vec3 dir)
{
edge=0.;
vec3 p, norm;
float d=100.;
float totdist=0.;
for (int i=0; i<RAY_STEPS; i++) {
if (d>det*totdist && totdist<25.0) {
p=from+totdist*dir;
d=de(p);
det=detail*exp(.13*totdist);
totdist+=d;
}
}
vec3 col=vec3(0., 0., 0.);
p-=(det-d)*dir;
norm=normal(p);
#ifdef SHOWONLYEDGES
col=1.-vec3(edge);
// show wireframe version
#else
col=(1.-abs(norm))*max(0.,1.-edge*.8);
// set normal as color with dark edges
#endif
totdist=clamp(totdist,0.,26.);
dir.y-=.02;
// float sunsize=7.-max(0.,texture(iChannel0,vec2(.6,.2)).x)*5.;
// 4.6: very bright, 7.6: small
float sunsize = 7.6;
#ifdef bass_smooth
sunsize -= 2.0 * vis_shift;
if (vis_version ==  1) {
sunsize -= clamp( 0.0 , 2.0 ,bass_smooth)*1.5*vis_intensity;
}
else if (vis_version ==  2) {
sunsize -= smoothstep( 0.0 , 2.0 ,audioLowSmooth)*1.4*vis_intensity;
}
else {
sunsize -= vis_intensity;
}
#else
sunsize -= smoothstep( 0.0 , 2.0 ,audioLowSmooth)*1.4;
#endif
// responsive sun size
float an=atan(dir.x,dir.y)+uTime*1.5;
// angle for drawing and rotating sun
float s=pow(clamp(1.0-length(dir.xy)*sunsize-abs(.2-mod_conv(an,.4)),0.,1.),.1);
// sun
float sb=pow(clamp(1.0-length(dir.xy)*(sunsize-.2)-abs(.2-mod_conv(an,.4)),0.,1.),.1);
// sun border
float sg=pow(clamp(1.0-length(dir.xy)*(sunsize-4.5)-.5*abs(.2-mod_conv(an,.4)),0.,1.),3.);
// sun rays
float y=mix(.45,1.2,pow(smoothstep(0.,1.,.75-dir.y),2.))*(1.-sb*.5);
// gradient sky
vec3 backg=vec3(0.5,0.,1.)*((1.-s)*(1.-sg)*y+(1.-sb)*sg*vec3(1.,.8,0.15)*3.);
backg+=vec3(1.,.9,.1)*s;
backg=max(backg,sg*vec3(1.,.9,.5));
col=mix(vec3(1.,.9,.3),col,exp(-.004*totdist*totdist));
// distant fading to sun color
if (totdist>25.) col=backg;
// hit background
col=pow(col,vec3(GAMMA,GAMMA,GAMMA))*BRIGHTNESS;
col=mix(vec3(length(col), length(col), length(col)),col,SATURATION);
#ifdef SHOWONLYEDGES
col=1.-vec3(length(col), length(col), length(col));
#else
col*=vec3(1.,.9,.85);
#ifdef NYAN
dir.yx =multiply(dir.yx,rot(dir.x));
vec2 ncatpos=(dir.xy+vec2(-3.+mod_conv(-t,6.),-.27));
vec4 ncat=nyan(ncatpos*5.);
vec4 rain=rainbow(ncatpos*10.+vec2(.8,.5));
if (totdist>8.) col=mix(col,max(vec3(.2,.2,.2),rain.xyz),rain.a*.9);
if (totdist>8.) col=mix(col,max(vec3(.2,.2,.2),ncat.xyz),ncat.a*.9);
#endif
#endif
return col;
}
vec3 move(inout vec3 dir) {
vec3 go=path(t);
vec3 adv=path(t+.7);
float hd=de(adv);
vec3 advec=normalize(adv-go);
float an=adv.x-go.x; an*=min(1.,abs(adv.z-go.z))*sign(adv.z-go.z)*.7;
dir.xy = multiply(dir.xy, transpose(mat2(cos(an),sin(an),-sin(an),cos(an))));
an=advec.y*1.7;
dir.yz = multiply(dir.yz, transpose(mat2(cos(an),sin(an),-sin(an),cos(an))));
an=atan(advec.x,advec.z);
dir.xz = multiply(dir.xz, transpose(mat2(cos(an),sin(an),-sin(an),cos(an))));
return go;
}
